  \begin{equation}\label{interlace}
\source{rigid-local-systems-multiplicative-eigenvalue-problem}
  0<b_1<a_2<b_2<\dots<a_{\ell-1}<b_{\ell}<n, \ \ m=\sum_{i=2}^{\ell} a_i-\sum_{i=1}^\ell b_i.
  \end{equation}

